mapper.update:
UPDATE user_ai_credits
SET used_credits = used_credits + #{creditsToUse},
    remaining_credits = remaining_credits - #{creditsToUse},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND remaining_credits >= #{creditsToUse}

mapper.select:
SELECT remaining_credits
FROM user_ai_credits
WHERE user_id = #{userId}
